// ---- Stats helpers ----

export const AD_COUNT = ADS.length;

export const AD_COUNT_BY_PLATFORM: Record<AdPlatform, number> = ADS.reduce(
  (acc, a) => {
    acc[a.platform] = (acc[a.platform] ?? 0) + 1;
    return acc;
  },
  {} as Record<AdPlatform, number>,
);

export const AD_COUNT_BY_VERTICAL: Record<AdVertical, number> = ADS.reduce(
  (acc, a) => {
    acc[a.vertical] = (acc[a.vertical] ?? 0) + 1;
    return acc;
  },
  {} as Record<AdVertical, number>,
);

export const AD_COUNT_BY_PATTERN: Record<AdPattern, number> = ADS.reduce(
  (acc, a) => {
    acc[a.pattern] = (acc[a.pattern] ?? 0) + 1;
    return acc;
  },
  {} as Record<AdPattern, number>,
);

